# Toy network: who can be reached from the accounting PC that took the update?
hosts = {  # name: (patched?, accepts the shared admin password?)
    "acct-pc": (False, True), "pc-2": (True, True), "pc-3": (False, True),
    "file-srv": (True, True), "dc-1": (True, True), "lab-pc": (True, False),
}
links = {"acct-pc": ["pc-2", "pc-3", "file-srv"], "pc-2": ["dc-1"],
         "pc-3": ["lab-pc"], "file-srv": ["dc-1"], "dc-1": [], "lab-pc": []}

def spread(use_credentials):
    hit, todo = {"acct-pc"}, ["acct-pc"]
    while todo:
        for nxt in links[todo.pop()]:
            patched, shared_pw = hosts[nxt]
            if nxt not in hit and (not patched or (use_credentials and shared_pw)):
                hit.add(nxt); todo.append(nxt)
    return sorted(hit)

print("exploit only:      ", spread(False))
print("exploit + creds:   ", spread(True))

# Output:
# exploit only:       ['acct-pc', 'pc-3']
# exploit + creds:    ['acct-pc', 'dc-1', 'file-srv', 'pc-2', 'pc-3']

# Inventory rows: (application, component, version). Made-up data.
inventory = [
    ("billing-api", "log4j-core", "2.14.1"),
    ("search",      "log4j-api",  "2.14.1"),   # API jar alone is not affected
    ("reports",     "log4j-core", "2.17.2"),
    ("legacy-crm",  "log4j-core", "2.15.0"),
]

def v(s):
    return tuple(int(x) for x in s.split("."))

# Java 8+ line (Apache Log4j security page and CVE records):
# CVE-2021-44228 fixed in 2.15.0, but that fix was incomplete
# (CVE-2021-45046, critical, fixed in 2.16.0); last follow-up fixed in 2.17.1
for app, comp, ver in inventory:
    if comp != "log4j-core":
        status = "not affected (no log4j-core)"
    elif v(ver) < (2, 15, 0):
        status = "CRITICAL: CVE-2021-44228, upgrade"
    elif v(ver) < (2, 16, 0):
        status = "CRITICAL: CVE-2021-45046, upgrade"
    elif v(ver) < (2, 17, 1):
        status = "upgrade: later Log4j CVEs"
    else:
        status = "ok"
    print(f"{app:12} {comp:11} {ver:7} {status}")

# Output:
# billing-api  log4j-core  2.14.1  CRITICAL: CVE-2021-44228, upgrade
# search       log4j-api   2.14.1  not affected (no log4j-core)
# reports      log4j-core  2.17.2  ok
# legacy-crm   log4j-core  2.15.0  CRITICAL: CVE-2021-45046, upgrade
